package com.lqq.supportflow.conversation.api;
import com.lqq.supportflow.conversation.domain.*; import com.lqq.supportflow.shared.AuthenticatedPrincipal; import java.io.IOException; import org.springframework.http.MediaType; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController @RequestMapping("/api/v1/customer/generations") public class GenerationEventsController { private final ConversationPort conversations; private final GenerationEventStore events; public GenerationEventsController(ConversationPort conversations,GenerationEventStore events){this.conversations=conversations;this.events=events;} @GetMapping(value="/{generationId}/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE) SseEmitter events(@AuthenticationPrincipal AuthenticatedPrincipal principal,@PathVariable Long generationId,@RequestHeader(value="Last-Event-ID",required=false) String lastEventId) throws IOException {if(!conversations.ownsGeneration(principal.tenantId(),principal.userId(),generationId))throw new IllegalArgumentException("generation does not belong to customer");SseEmitter emitter=new SseEmitter(10_000L);for(GenerationEvent event:events.readAfter(generationId,lastEventId))emitter.send(SseEmitter.event().id(event.id()).name(event.type()).data(event.data(),MediaType.APPLICATION_JSON));emitter.complete();return emitter;}}
